  const alarms = sourceAlarms.filter(alarm => Date.parse(alarm.raisedAt) >= cutoff && (applied.severity === "All" || alarm.severity === applied.severity) && (applied.status === "All" || (applied.status === "Unacknowledged" ? alarm.sourceStatus === "Active" && alarm.klinthruStatus !== "Acknowledged" : alarm.sourceStatus === applied.status || alarm.klinthruStatus === applied.status)) && matchesAsset(alarm.tagId) && `${alarm.tagId} ${alarm.description}`.toLowerCase().includes(applied.query.toLowerCase())).sort((a, b) => Date.parse(b.raisedAt) - Date.parse(a.raisedAt));
  const events = data.events.filter(event => Date.parse(event.occurredAt) >= cutoff && (applied.severity === "All" || event.severity === applied.severity) && matchesAsset(event.tagId) && `${event.eventType} ${event.description} ${event.eventId}`.toLowerCase().includes(applied.query.toLowerCase()));
  const selected = sourceAlarms.find(alarm => alarm.id === selectedId);
  const selectedEvent = data.events.find(event => event.id === eventId), eventPages = Math.max(1,Math.ceil(events.length/25)), currentEventPage = Math.min(eventPage,eventPages);
  const timeline = [...alarms.map(alarm => ({ id: alarm.id, at: alarm.raisedAt, type: "Alarm", description: alarm.description })), ...events.map(event => ({ id: event.id, at: event.occurredAt, type: event.eventType, description: event.description }))].sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
  const active = sourceAlarms.filter(alarm => alarm.sourceStatus === "Active");
  const known = data.tags.some(tag => tag.reading);
  const count = (value: number) => known ? number(value, 0) : unavailable;
